<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Par\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Civi\Lughauth\Features\OAuth\Par\Application\Usecase\PushAuthorizationRequest\PushAuthorizationParams;
use Civi\Lughauth\Features\OAuth\Par\Application\Usecase\PushAuthorizationRequest\PushAuthorizationUsecase;
use Civi\Lughauth\Features\OAuth\Par\Domain\Exception\ParException;

class ParController
{
    public function __construct(
        private readonly PushAuthorizationUsecase $usecase,
    ) {
    }

    #[OA\Post(
        path: '/oauth/openid/{tenant}/par',
        summary: 'Pushed Authorization Request — RFC 9126',
        description: 'Accepts authorization parameters server-to-server and returns a short-lived request_uri. The client then redirects the user-agent to /authorize with only client_id and request_uri.',
        tags: ['OIDC'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        requestBody: new OA\RequestBody(
            required: true,
            content: new OA\MediaType(
                mediaType: 'application/x-www-form-urlencoded',
                schema: new OA\Schema(
                    required: ['client_id', 'response_type', 'redirect_uri'],
                    properties: [
                        new OA\Property(property: 'client_id', type: 'string'),
                        new OA\Property(property: 'client_secret', type: 'string'),
                        new OA\Property(property: 'response_type', type: 'string', example: 'code'),
                        new OA\Property(property: 'redirect_uri', type: 'string'),
                        new OA\Property(property: 'scope', type: 'string', example: 'openid email'),
                        new OA\Property(property: 'state', type: 'string'),
                        new OA\Property(property: 'nonce', type: 'string'),
                        new OA\Property(property: 'code_challenge', type: 'string'),
                        new OA\Property(property: 'code_challenge_method', type: 'string', enum: ['S256', 'plain']),
                    ]
                )
            )
        ),
        responses: [
            new OA\Response(
                response: 201,
                description: 'PAR request created',
                content: new OA\JsonContent(properties: [
                    new OA\Property(property: 'request_uri', type: 'string', example: 'urn:ietf:params:oauth:request_uri:abc123'),
                    new OA\Property(property: 'expires_in', type: 'integer', example: 60),
                ])
            ),
            new OA\Response(response: 400, description: 'Invalid request parameters'),
            new OA\Response(response: 401, description: 'Client authentication failed'),
        ]
    )]
    public function post(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        try {
            return $this->handlePost($request, $response, $args);
        } catch (ParException $ex) {
            $payload = ['error' => $ex->error(), 'error_description' => $ex->getMessage()];
            $encoded = json_encode($payload);
            $response->getBody()->write($encoded !== false ? $encoded : '{}');
            return $response->withStatus($ex->statusCode())->withHeader('Content-Type', 'application/json');
        }
    }

    private function handlePost(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $params = (array) ($request->getParsedBody() ?? []);

        [$clientId, $clientSecret] = $this->resolveClientCredentials($request, $params);

        $authParams = $this->extractAuthParams($params, $clientId);

        $pushParams = new PushAuthorizationParams(
            tenant: $tenant,
            clientId: $clientId,
            clientSecret: $clientSecret,
            authParams: $authParams,
        );

        $result = $this->usecase->push($pushParams);

        $payload = [
            'request_uri' => $result->requestUri,
            'expires_in' => $result->expiresIn,
        ];
        $encoded = json_encode($payload);
        $response->getBody()->write($encoded !== false ? $encoded : '{}');
        return $response->withStatus(201)->withHeader('Content-Type', 'application/json');
    }

    private function resolveClientCredentials(ServerRequestInterface $request, array $params): array
    {
        $serverParams = $request->getServerParams();
        if (isset($serverParams['PHP_AUTH_USER']) && isset($serverParams['PHP_AUTH_PW'])) {
            return [(string) $serverParams['PHP_AUTH_USER'], (string) $serverParams['PHP_AUTH_PW']];
        }

        $clientId = (string) ($params['client_id'] ?? '');
        $clientSecret = (string) ($params['client_secret'] ?? '');

        if ($clientId === '') {
            throw ParException::invalidRequest('client_id is required');
        }

        return [$clientId, $clientSecret];
    }

    private function extractAuthParams(array $params, string $clientId): array
    {
        $authParams = $params;
        unset($authParams['client_secret']);

        if (empty($authParams['client_id'])) {
            $authParams['client_id'] = $clientId;
        }

        return $authParams;
    }
}
